    /**
     * Set the expiration of the transaction to be a specific epoch.
     */
    fun `expiration`(`epoch`: kotlin.ULong): TransactionBuilder
    
    /**
     * Convert this builder into a transaction.
     */
    fun `finish`(): Transaction
    
    /**
     * Add gas coins that will be consumed. Optional.
     */
    fun `gas`(`objectRefs`: List<ObjectReference>): TransactionBuilder
    
    /**
     * Set the gas budget for the transaction.
     */
    fun `gasBudget`(`budget`: kotlin.ULong): TransactionBuilder
    
    /**
     * Set the gas price for the transaction.
     */
    fun `gasPrice`(`price`: kotlin.ULong): TransactionBuilder
    
    /**
     * Set the gas station sponsor.
     */
    fun `gasStationSponsor`(`url`: kotlin.String, `duration`: java.time.Duration? = null, `headers`: Map<kotlin.String, List<kotlin.String>>? = null): TransactionBuilder
    
    /**
     * Make a move vector from a list of elements. The elements must all be of
     * the type indicated by `type_tag`.
     */
    fun `makeMoveVec`(`elements`: List<MoveArg>, `typeTag`: TypeTag, `name`: kotlin.String): TransactionBuilder
    
    /**
     * Merge multiple coins into one.
     *
     * This method combines the balances of multiple coins of the same coin
     * type into a single coin. The `primary_coin` will receive the balances
     * from all `consumed_coins`. After merging, the `consumed_coins` will
     * be consumed and no longer exist.
     */
    fun `mergeCoins`(`primaryCoin`: PtbArgument, `consumedCoins`: List<PtbArgument>): TransactionBuilder
    
    /**
     * Call a Move function with the given arguments.
     */
    fun `moveCall`(`package`: Address, `module`: Identifier, `function`: Identifier, `arguments`: List<PtbArgument> = listOf(), `typeArgs`: List<TypeTag> = listOf(), `names`: List<kotlin.String> = listOf()): TransactionBuilder
    
    /**
