 * @suppress
 */
public object FfiConverterTypeGasCostSummary: FfiConverterRustBuffer<GasCostSummary> {
    override fun read(buf: ByteBuffer): GasCostSummary {
        return GasCostSummary(
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
