            }
            is ObjectIn.Data -> {
                buf.putInt(2)
                FfiConverterTypeVersion.write(value.`version`, buf)
                FfiConverterTypeDigest.write(value.`digest`, buf)
                FfiConverterTypeOwner.write(value.`owner`, buf)
