/**
 * Flag use to disambiguate the signature schemes supported by IOTA.
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * signature-scheme = ed25519-flag / secp256k1-flag / secp256r1-flag /
 * multisig-flag / bls-flag / zklogin-auth-flag / passkey-auth-flag /
 * move-auth-flag
 * ed25519-flag        = %x00
 * secp256k1-flag      = %x01
 * secp256r1-flag      = %x02
 * multisig-flag       = %x03
 * bls-flag            = %x04
 * zklogin-auth-flag   = %x05
 * passkey-auth-flag   = %x06
 * move-auth-flag      = %x07
 * ```
 */

enum class SignatureScheme(val value: kotlin.UByte) {
    
    ED25519(0u),
    SECP256K1(1u),
    SECP256R1(2u),
    MULTISIG(3u),
    BLS12381(4u),
    ZK_LOGIN_AUTHENTICATOR(5u),
    PASSKEY_AUTHENTICATOR(6u),
    MOVE_AUTHENTICATOR(7u);
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeSignatureScheme: FfiConverterRustBuffer<SignatureScheme> {
    override fun read(buf: ByteBuffer) = try {
